css:
/* Check / uncheck */

@keyframes check-squash {
  0% {
    scale: 1;
  }

  30% {
    scale: 0.82;
  }

  100% {
    scale: 1;
  }
}

@keyframes check-ripple {
  from {
    opacity: 0.55;
    scale: 1;
  }

  to {
    opacity: 0;
    scale: 1.9;
  }
}

@keyframes check-wash {
  0%, 25% {
    opacity: 0.7;
  }

  100% {
    opacity: 0;
  }
}
/* Shared */

@keyframes mira-fade-in {
  from {
    opacity: 0;
  }
}

@keyframes mira-fade-out {
  to {
    opacity: 0;
  }
}

@keyframes mira-hold {
  from {
    opacity: 1;
  }

  to {
    opacity: 1;
  }
}
/* A · Spring push: iOS-style, new page from the right on SPRING_SCREEN, old page parallaxes left and dims */

@keyframes a-push-in {
  from {
    translate: 100% 0;
  }
}

@keyframes a-push-out {
  to {
    translate: -30% 0;
    filter: brightness(0.85);
  }
}

@keyframes a-pop-in {
  from {
    translate: -30% 0;
    filter: brightness(0.85);
  }
}

@keyframes a-pop-out {
  to {
    translate: 100% 0;
  }
}

::view-transition-group(a-page) {
  animation-duration: 481ms;
  animation-timing-function: linear(0, 0.0302, 0.1017, 0.1931, 0.2911, 0.3875, 0.4776, 0.5591, 0.631, 0.6933, 0.7466, 0.7917, 0.8295, 0.861, 0.887, 0.9084, 0.926, 0.9403, 0.952, 0.9614, 0.9691, 0.9752, 0.9802, 0.9842, 0.9874, 0.9899, 0.992, 0.9936, 0.9949, 0.996, 0.9968, 0.9975, 1);
}

::view-transition-old(a-page) {
  animation-name: a-push-out;
  mix-blend-mode: normal;
}

::view-transition-new(a-page) {
  animation-name: a-push-in;
  mix-blend-mode: normal;
}

:active-view-transition-type(back)::view-transition-old(a-page) {
  animation-name: a-pop-out;
  z-index: 1;
}

:active-view-transition-type(back)::view-transition-new(a-page) {
  animation-name: a-pop-in;
}
/* B · The tapped row grows into Item detail's name card (SPRING_TRAVEL); the settings button opens Settings as a circle */

@keyframes b-page-out {
  to {
    opacity: 0;
    scale: 0.97;
  }
}

@keyframes b-page-in {
  from {
    opacity: 0;
    translate: 0 16px;
  }
}

@keyframes b-page-back-out {
  to {
    opacity: 0;
    translate: 0 16px;
  }
}

@keyframes b-page-back-in {
  from {
    opacity: 0;
    scale: 0.97;
  }
}

@keyframes b-reveal-open {
  from {
    clip-path: circle(0px at 361px 94px);
  }

  to {
    clip-path: circle(880px at 361px 94px);
  }
}

@keyframes b-reveal-close {
  from {
    clip-path: circle(880px at 361px 94px);
  }

  to {
    clip-path: circle(0px at 361px 94px);
  }
}

@keyframes b-under {
  to {
    scale: 0.97;
    filter: brightness(0.9);
  }
}

@keyframes b-under-back {
  from {
    scale: 0.97;
    filter: brightness(0.9);
  }
}

::view-transition-group(b-hero) {
  animation-duration: 260ms;
  animation-timing-function: linear(0, 0.0215, 0.075, 0.1472, 0.2289, 0.3134, 0.3964, 0.4751, 0.5477, 0.6136, 0.6722, 0.7239, 0.7688, 0.8076, 0.8407, 0.8689, 0.8926, 0.9124, 0.929, 0.9427, 0.9539, 0.9632, 0.9707, 0.9768, 0.9818, 0.9858, 0.9889, 0.9915, 0.9935, 0.995, 0.9963, 0.9972, 1);
}

@keyframes b-hero-out {
  0% {
    opacity: 1;
  }

  40%, 100% {
    opacity: 0;
  }
}

@keyframes b-hero-in {
  0%, 15% {
    opacity: 0;
  }

  55%, 100% {
    opacity: 1;
  }
}

::view-transition-old(b-hero) {
  animation-name: b-hero-out;
  mix-blend-mode: normal;
  height: 100%;
  object-fit: cover;
  object-position: left top;
}

::view-transition-new(b-hero) {
  animation-name: b-hero-in;
  mix-blend-mode: normal;
  height: 100%;
  object-fit: cover;
  object-position: left top;
}

::view-transition-group(b-page) {
  animation-duration: 314ms;
  animation-timing-function: cubic-bezier(0.23, 1, 0.32, 1);
}

::view-transition-old(b-page) {
  animation-name: b-page-out;
}

::view-transition-new(b-page) {
  animation-name: b-page-in;
}

:active-view-transition-type(back)::view-transition-old(b-page) {
  animation-name: b-page-back-out;
}

:active-view-transition-type(back)::view-transition-new(b-page) {
  animation-name: b-page-back-in;
}

::view-transition-group(b-reveal) {
  animation-duration: 380ms;
  animation-timing-function: linear(0, 0.0215, 0.075, 0.1472, 0.2289, 0.3134, 0.3964, 0.4751, 0.5477, 0.6136, 0.6722, 0.7239, 0.7688, 0.8076, 0.8407, 0.8689, 0.8926, 0.9124, 0.929, 0.9427, 0.9539, 0.9632, 0.9707, 0.9768, 0.9818, 0.9858, 0.9889, 0.9915, 0.9935, 0.995, 0.9963, 0.9972, 1);
}

::view-transition-old(b-reveal) {
  animation-name: b-under;
  mix-blend-mode: normal;
}

::view-transition-new(b-reveal) {
  animation-name: b-reveal-open;
  mix-blend-mode: normal;
}

:active-view-transition-type(back)::view-transition-old(b-reveal) {
  animation-name: b-reveal-close;
  z-index: 1;
}

:active-view-transition-type(back)::view-transition-new(b-reveal) {
  animation-name: b-under-back;
}
/* C · Depth: forward pushes the old page past you and the new one rises from behind; back reverses */

@keyframes c-fwd-out {
  0% {
    opacity: 1;
    scale: 1;
  }

  45% {
    opacity: 0;
  }

  100% {
    opacity: 0;
    scale: 1.06;
  }
}

@keyframes c-fwd-in {
  from {
    opacity: 0;
    scale: 0.92;
  }
}

@keyframes c-back-out {
  0% {
    opacity: 1;
    scale: 1;
  }

  45% {
    opacity: 0;
  }

  100% {
    opacity: 0;
    scale: 0.92;
  }
}

@keyframes c-back-in {
  from {
    opacity: 0;
    scale: 1.06;
  }
}

::view-transition-group(c-page) {
  animation-duration: 358ms;
  animation-timing-function: linear(0, 0.0217, 0.0755, 0.1482, 0.2302, 0.315, 0.3983, 0.4771, 0.5498, 0.6157, 0.6743, 0.7258, 0.7706, 0.8092, 0.8422, 0.8702, 0.8937, 0.9134, 0.9298, 0.9434, 0.9546, 0.9637, 0.9712, 0.9772, 0.9821, 0.986, 0.9891, 0.9916, 0.9936, 0.9951, 0.9963, 0.9973, 1);
}

::view-transition-old(c-page) {
  animation-name: c-fwd-out;
}

::view-transition-new(c-page) {
  animation-name: c-fwd-in;
}

:active-view-transition-type(back)::view-transition-old(c-page) {
  animation-name: c-back-out;
}

:active-view-transition-type(back)::view-transition-new(c-page) {
  animation-name: c-back-in;
}

@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(a-page) {
    animation-duration: 200ms;
    animation-timing-function: ease-out;
  }

  ::view-transition-old(a-page) {
    animation-name: mira-fade-out;
    z-index: auto;
  }

  ::view-transition-new(a-page) {
    animation-name: mira-fade-in;
  }

  :active-view-transition-type(back)::view-transition-old(a-page) {
    animation-name: mira-fade-out;
    z-index: auto;
  }

  :active-view-transition-type(back)::view-transition-new(a-page) {
    animation-name: mira-fade-in;
  }

  ::view-transition-group(b-page) {
    animation-duration: 200ms;
    animation-timing-function: ease-out;
  }

  ::view-transition-old(b-page) {
    animation-name: mira-fade-out;
    z-index: auto;
  }

  ::view-transition-new(b-page) {
    animation-name: mira-fade-in;
  }

  :active-view-transition-type(back)::view-transition-old(b-page) {
    animation-name: mira-fade-out;
    z-index: auto;
  }

  :active-view-transition-type(back)::view-transition-new(b-page) {
    animation-name: mira-fade-in;
  }

  ::view-transition-group(b-reveal) {
    animation-duration: 200ms;
    animation-timing-function: ease-out;
  }

  ::view-transition-old(b-reveal) {
    animation-name: mira-fade-out;
    z-index: auto;
  }

  ::view-transition-new(b-reveal) {
    animation-name: mira-fade-in;
  }

  :active-view-transition-type(back)::view-transition-old(b-reveal) {
    animation-name: mira-fade-out;
    z-index: auto;
  }

  :active-view-transition-type(back)::view-transition-new(b-reveal) {
    animation-name: mira-fade-in;
  }

  ::view-transition-group(c-page) {
    animation-duration: 200ms;
    animation-timing-function: ease-out;
  }

  ::view-transition-old(c-page) {
    animation-name: mira-fade-out;
    z-index: auto;
  }

  ::view-transition-new(c-page) {
    animation-name: mira-fade-in;
  }

  :active-view-transition-type(back)::view-transition-old(c-page) {
    animation-name: mira-fade-out;
    z-index: auto;
  }

  :active-view-transition-type(back)::view-transition-new(c-page) {
    animation-name: mira-fade-in;
  }

  ::view-transition-group(b-hero) {
    animation-duration: 200ms;
    animation-timing-function: ease-out;
  }
}

0VnSKpiX.css:
& svg {
  stroke-width: 3;
}

& path {
  stroke-dasharray: 23 23;
  stroke-dashoffset: -23;
  transition: stroke-dashoffset 120ms cubic-bezier(0.5, 0, 0.75, 0);
}

[data-state="checked"] & path {
  stroke-dashoffset: 0;
  transition: stroke-dashoffset 220ms cubic-bezier(0.23, 1, 0.32, 1) 70ms;
}

@media (prefers-reduced-motion: reduce) {
  & path {
    stroke-dashoffset: 0;
    transition: none;
  }
}

