}

1TO3bgwa.css:
clip-path: circle(0% at 50% 50%);
transition: clip-path 180ms cubic-bezier(0.5, 0, 0.75, 0);

[data-state="checked"] & {
  clip-path: circle(75% at 50% 50%);
  transition: clip-path 254ms linear(0, 0.0141, 0.0508, 0.1031, 0.1652, 0.2328, 0.3026, 0.3722, 0.4397, 0.5039, 0.564, 0.6195, 0.6701, 0.7158, 0.7567, 0.793, 0.825, 0.8531, 0.8774, 0.8984, 0.9165, 0.9318, 0.9449, 0.9558, 0.965, 0.9726, 0.9789, 0.9841, 0.9883, 0.9916, 0.9943, 0.9964, 1);
}

@media (prefers-reduced-motion: reduce) {
  opacity: 0;
  clip-path: none;
  transition: opacity 150ms ease-out;

  [data-state="checked"] & {
    opacity: 1;
    clip-path: none;
    transition: opacity 150ms ease-out;
  }
}

